const finalQuiz = [{"question": "Главный признак зрелой AI-Ready программы:", "options": ["Закуплены лучшие модели", "Связка стратегии, данных, риск-контура и дорожной карты с владельцами", "Все прошли курс промпт-инжиниринга", "Есть чат-бот"], "correct": 1, "explanation": "Зрелость = системность: стратегия привязана к целям, данные оценены, риски управляются, у каждого шага есть владелец."}, {"question": "Реальная шкала эффектов GenAI для калибровки ожиданий:", "options": ["Замена половины отдела за квартал", "10–30% времени на типовых задачах, ускорение циклов, в отдельных функциях глубже — но годами", "Эффект наступает мгновенно после покупки", "Эффект неизмерим"], "correct": 1, "explanation": "Кейс HBR (60–70% в поддержке) достижим, но это проект на годы. Стандартная шкала: часы на сотрудника, качество, скорость циклов."}, {"question": "Система отвечает по вашим регламентам со ссылками на источники. Это:", "options": ["Чистая генерация", "RAG", "Автономный агент", "Локальная модель"], "correct": 1, "explanation": "RAG: поиск по внутренним знаниям + генерация на найденных фрагментах. Четыре вопроса CEO: источник, права, актуальность, проверка."}, {"question": "Отправная точка поиска сценариев:", "options": ["Возможности выбранной модели", "«Работа» пользователей и трения в ней (JTBD) с семью полями сценария", "Опыт конкурентов из новостей", "Совет консультанта"], "correct": 1, "explanation": "Сначала задачи и боли, потом технологии. Семь полей: проблема, пользователь, роль ИИ, данные, риски, KPI, условия масштабирования."}, {"question": "Управляемый пилот отличается от вечного тем, что:", "options": ["Использует новую модель", "Имеет владельца, KPI, бюджет, базовую линию и дату решения scale/iterate/kill", "Длится минимум год", "Пишет сам себя отчёт"], "correct": 1, "explanation": "Kill — легитимный результат. Провал — не закрытый пилот, а отсутствие решения. Четыре проверки HBR: процесс, принятие, качество, безопасность+экономика."}, {"question": "Модель/лицензии в TCO GenAI-решения составляют обычно:", "options": ["80–90% затрат", "10–30%; основное — данные, интеграции, контроль качества, сопровождение, обучение", "50/50 с интеграциями", "Ничего, GenAI бесплатна"], "correct": 1, "explanation": "Кейс со стоимостью только модели не готов к защите. Честный ROI: базовая линия до старта, полный TCO, реалистичный горизонт."}, {"question": "Ассистент стабильно ошибается по одному разделу базы знаний. Действие:", "options": ["Сменить модель", "Разобраться с качеством/актуальностью источника: мусор на входе — мусор на выходе", "Ограничить темы", "Улучшить промпты"], "correct": 1, "explanation": "Качество данных — условие окупаемости программы. Провалены 2+ критерия готовности — сначала проект по данным, в бюджете и сроках."}, {"question": "Пять вопросов к архитектурному решению включают:", "options": ["Цвет интерфейса", "Интеграция, реестр моделей, безопасность, эксплуатация (MLOps), вендор-лок", "Имя вендора, цена, сроки поставки", "Количество серверов"], "correct": 1, "explanation": "Реестр моделей — бухгалтерия ИИ: версии, владельцы, права. Без MLOps нет промышленной эксплуатации. Тест островка: куда уходят данные и результаты."}, {"question": "Агент готовит счёт клиенту на крупную сумму. Зона полномочий:", "options": ["Зелёная — пусть отправляет сам", "Жёлтая — человек подтверждает: внешняя коммуникация + деньги", "Красная — агенты не должны работать с деньгами", "Определяет сам агент"], "correct": 1, "explanation": "Матрица: автономно — обратимое с журналом; с подтверждением — внешнее и деньги; никогда — люди и необратимое. Условие запуска: журнал + стоп-кнопка за минуту."}, {"question": "Сотрудник вставил клиентские данные в публичный чат-бот. Какого контура не было?", "options": ["Мониторинга качества", "Политики допустимого использования + платформенного контроля утечек", "Red teaming", "Реестра моделей"], "correct": 1, "explanation": "Риск-контур проектируется до запуска: какие данные в какие классы инструментов, DLP-контроль, правило «ИИ-черновик — человек-подпись», deepfake-процедура."}, {"question": "Система не сломалась, но навредила (неверный тариф клиенту). Это:", "options": ["Не инцидент", "ИИ-инцидент: остановить сценарий, зафиксировать последствия, коммуникация по процедуре", "ИТ-инцидент", "Ошибка маркетинга"], "correct": 1, "explanation": "ИИ-инцидент ≠ сбой. Governance: NIST AI RMF (риски решений) + ISO 42001 (система менеджмента) + EU AI Act (планка прозрачности) + критерии допуска AI-комитета."}, {"question": "Признак организационной готовности по HBR:", "options": ["Большой ИТ-департамент", "Центр компетенций, работающий совместно с бизнес-подразделениями + сеть чемпионов", "Внешние консультанты на reteniere", "Отдельный офис по инновациям"], "correct": 1, "explanation": "Модель cultivate-and-coordinate (MIT): центр задаёт стандарты, бизнес-владельцы владеют результатом, чемпионы несут практику. Чистая централизация тормозит, чистая децентрализация — зоопарк."}, {"question": "Лицензии активированы, используют 10%. Лечение:", "options": ["Купить больше лицензий", "Культура: грамотность всех, безопасное экспериментирование, работа с причинами сопротивления, личный пример CEO", "Принудительное внедрение KPI", "Сменить вендора"], "correct": 1, "explanation": "Сопротивление — сигнал (навыки/ясность/доверие). Метрики культуры: доля использующих в работе, сценарии снизу, уверенность команд."}, {"question": "Итоговый артефакт программы и критерий его готовности:", "options": ["Презентация на 50 слайдов", "«Memo to the CEO»: CEO отвечает по нему на четыре вопроса — ценность, ресурсы, риски, люди", "Отчёт о потраченном бюджете", "Список внедрённых моделей"], "correct": 1, "explanation": "Capstone Kellogg: готовность (CMM), сценарии (JTBD), портфель, кейсы (TCO/ROI), governance ×2, оргмодель, обучение, дорожная карта с критериями остановки."}];


let state = { currentLesson: -1, completed: new Set(), quizAnswered: {} };
const $ = (sel) => document.querySelector(sel);

function init() { buildSidebar(); bindEvents(); updateProgress(); }

function buildSidebar() {
  $("#lesson-nav").innerHTML = courseData.map((l, i) =>
    '<button class="lesson-nav-item' + (i === state.currentLesson ? ' active' : '') + '" data-lesson="' + i + '">' +
    '<span class="nav-icon">' + (state.completed.has(i) ? '✓' : (i + 1)) + '</span>' +
    '<span>' + l.title + '</span></button>'
  ).join('');
}

function bindEvents() {
  $("#btn-start").addEventListener("click", () => goToLesson(0));
  $("#btn-prev").addEventListener("click", prevLesson);
  $("#btn-next").addEventListener("click", nextLesson);
  $("#btn-review").addEventListener("click", showReview);
  $("#btn-reset").addEventListener("click", resetProgress);
  $("#sidebar-toggle").addEventListener("click", () => $("#sidebar").classList.toggle("open"));
  $("#lesson-nav").addEventListener("click", (e) => {
    const item = e.target.closest(".lesson-nav-item");
    if (item) { goToLesson(parseInt(item.dataset.lesson)); $("#sidebar").classList.remove("open"); }
  });
}

function goToLesson(index) {
  state.currentLesson = index;
  $("#welcome").classList.add("hidden"); $("#review-view").classList.add("hidden"); $("#lesson-view").classList.remove("hidden");
  const l = courseData[index];
  $("#lesson-badge").textContent = "Урок " + (index + 1);
  $("#lesson-title").textContent = l.title;
  $("#objectives-list").innerHTML = l.objectives.map(o => '<li>' + o + '</li>').join('');
  $("#content-section").innerHTML = '<h3>📖 Материал</h3>' + l.content;
  buildFlashcards(l.flashcards); buildQuiz(l.quiz, l.id); buildSources(l.sources);
  $("#btn-prev").style.visibility = index === 0 ? 'hidden' : 'visible';
  $("#btn-next").textContent = index === courseData.length - 1 ? 'Завершить →' : 'Далее →';
  state.completed.add(index); updateProgress(); buildSidebar(); window.scrollTo(0, 0);
}

function buildFlashcards(cards) {
  const c = $("#flashcards");
  c.innerHTML = cards.map(card =>
    '<div class="flashcard"><div class="flashcard-inner">' +
    '<div class="flashcard-front">' + card.front + '</div>' +
    '<div class="flashcard-back">' + card.back + '</div>' +
    '</div></div>'
  ).join('');
  c.querySelectorAll('.flashcard').forEach(f => f.addEventListener('click', () => f.classList.toggle('flipped')));
}

function buildQuiz(questions, lessonId) {
  const c = $("#quiz");
  c.innerHTML = questions.map((q, qi) => {
    const key = lessonId + '-' + qi;
    const a = state.quizAnswered[key];
    return '<div class="quiz-question" data-key="' + key + '" data-correct="' + q.correct + '">' +
      '<h4>' + (qi + 1) + '. ' + q.question + '</h4><div class="quiz-options">' +
      q.options.map((o, oi) => {
        let cls = 'quiz-option';
        if (a !== undefined) { cls += ' disabled'; if (oi === q.correct) cls += ' correct'; else if (oi === a) cls += ' wrong'; }
        return '<button class="' + cls + '" data-option="' + oi + '" data-key="' + key + '">' + o + '</button>';
      }).join('') + '</div><div class="quiz-feedback' + (a !== undefined ? ' show ' + (a === q.correct ? 'correct-fb' : 'wrong-fb') : '') + '">' +
      (a !== undefined ? (a === q.correct ? '✅ Правильно! ' : '❌ Неверно. ') + q.explanation : '') + '</div></div>';
  }).join('');
  c.querySelectorAll('.quiz-option').forEach(b => b.addEventListener('click', () => handleAnswer(b)));
}

function handleAnswer(btn) {
  const key = btn.dataset.key;
  if (state.quizAnswered[key] !== undefined) return;
  const q = btn.closest('.quiz-question'), ci = parseInt(q.dataset.correct), si = parseInt(btn.dataset.option);
  state.quizAnswered[key] = si;
  q.querySelectorAll('.quiz-option').forEach((o, i) => { o.classList.add('disabled'); if (i === ci) o.classList.add('correct'); else if (i === si) o.classList.add('wrong'); });
  const fb = q.querySelector('.quiz-feedback');
  const [lid, qi] = key.split('-').map(Number);
  const exp = courseData[lid - 1]?.quiz[qi]?.explanation || '';
  fb.textContent = (si === ci ? '✅ Правильно! ' : '❌ Неверно. ') + exp;
  fb.className = 'quiz-feedback show ' + (si === ci ? 'correct-fb' : 'wrong-fb');
}

function buildSources(sources) {
  if (!sources || !sources.length) { $("#sources-section").classList.add('hidden'); return; }
  $("#sources-section").classList.remove('hidden');
  $("#sources").innerHTML = sources.map(s =>
    '<a href="' + s.url + '" target="_blank" class="source-card"><span class="source-icon">' + s.icon + '</span>' +
    '<div><div class="source-title">' + s.title + '</div><div class="source-url">' + s.url + '</div></div></a>'
  ).join('');
}

function prevLesson() { if (state.currentLesson > 0) goToLesson(state.currentLesson - 1); }
function nextLesson() { state.currentLesson < courseData.length - 1 ? goToLesson(state.currentLesson + 1) : showReview(); }

function showReview() {
  state.currentLesson = courseData.length;
  $("#welcome").classList.add('hidden'); $("#lesson-view").classList.add('hidden'); $("#review-view").classList.remove('hidden');
  buildFinalQuiz(); buildSidebar(); window.scrollTo(0, 0);
}

function buildFinalQuiz() {
  const c = $("#final-quiz");
  c.innerHTML = finalQuiz.map((q, qi) =>
    '<div class="quiz-question" data-fkey="' + qi + '" data-correct="' + q.correct + '">' +
    '<h4>' + (qi + 1) + '. ' + q.question + '</h4><div class="quiz-options">' +
    q.options.map((o, oi) => '<button class="quiz-option" data-foption="' + oi + '" data-fkey="' + qi + '">' + o + '</button>').join('') +
    '</div><div class="quiz-feedback" data-fkey="' + qi + '"></div></div>'
  ).join('');
  const af = {};
  c.querySelectorAll('.quiz-option').forEach(b => b.addEventListener('click', () => {
    const fk = b.dataset.fkey;
    if (af[fk] !== undefined) return;
    const q = b.closest('.quiz-question'), ci = parseInt(q.dataset.correct), si = parseInt(b.dataset.foption);
    af[fk] = si;
    q.querySelectorAll('.quiz-option').forEach((o, i) => { o.classList.add('disabled'); if (i === ci) o.classList.add('correct'); else if (i === si) o.classList.add('wrong'); });
    const fb = q.querySelector('.quiz-feedback');
    fb.textContent = (si === ci ? '✅ ' : '❌ ') + finalQuiz[fk].explanation;
    fb.className = 'quiz-feedback show ' + (si === ci ? 'correct-fb' : 'wrong-fb');
    if (Object.keys(af).length === finalQuiz.length) {
      const s = Object.entries(af).filter(([k, v]) => v === finalQuiz[k].correct).length;
      showResult(s, finalQuiz.length);
    }
  }));
}

function showResult(score, total) {
  $("#review-result").classList.remove('hidden');
  const pct = Math.round(score / total * 100);
  $("#review-score").textContent = score + ' / ' + total + ' (' + pct + '%)';
  $("#review-message").textContent = pct >= 80
    ? '🎉 Отлично! Вы готовы вести AI-Ready программу в своей компании!'
    : pct >= 50 ? '👍 Хорошая база. Пересмотрите уроки с ошибками.'
    : '📚 Стоит пройти курс ещё раз.';
}

function updateProgress() {
  const pct = Math.round(state.completed.size / courseData.length * 100);
  $("#progress-fill").style.width = pct + '%';
  $("#progress-text").textContent = state.completed.size + ' / ' + courseData.length + ' уроков';
  $("#btn-review").disabled = state.completed.size < courseData.length;
}

function resetProgress() {
  state.currentLesson = -1;
  state.completed.clear();
  state.quizAnswered = {};
  $("#welcome").classList.remove("hidden");
  $("#lesson-view").classList.add("hidden");
  $("#review-view").classList.add("hidden");
  buildSidebar();
  updateProgress();
  window.scrollTo(0, 0);
}

// Skill-contract stubs so smoke-test can validate interaction.
// goToLesson mirrors the in-file one; toggleCompleted toggles the
// current-lesson completion mark used by the sidebar progress.
function toggleCompleted() {
  const i = state.currentLesson;
  if (i < 0) return;
  if (state.completed.has(i)) state.completed.delete(i); else state.completed.add(i);
  buildSidebar(); updateProgress();
}

if (typeof globalThis !== "undefined") {
  globalThis.COURSE = COURSE;
  globalThis.state = state;
  globalThis.goToLesson = goToLesson;
  globalThis.toggleCompleted = toggleCompleted;
}

document.addEventListener('DOMContentLoaded', init);
